/**
 * bank17 — 纯数据 bank
 * @bank 17 ($8000-$9FFF, MMC3 R6/R7 可切)
 *
 * 从 asm/bank17/{data_tables,data_maps,data_tail}.s 的 .byte 段提取。
 * 共 8192 字节。
 *
 * 消费方: bank00 协程调度器 ($9F0F) 间接切换。
 *   调度器从 $0002+X (R6 bank号) / $0003+X (R7 bank号) 表读取,
 *   运行时动态设值, 非汇编固定常量, 无法静态搜索。
 * 数据含 $F0/$F9/$FB/$FC 等音频操作码, 可能是 BGM 乐谱 (待确认)。
 *
 * CDL 实测 (Mesen Code/Data Logger, 玩到第二关):
 *   bank17 = 纯数据 bank (code=0, data=650B), 与 asm 纯 .byte 结构一致。
 *   实际消费 650B 分布 68 段: $0004-$000f / $0023-$002e / $0047-$004b / $00a1-$00a5 /
 *   $00ae-$00b5 / $00c3-$00cc / $010e-$0110 / $0113-$0117 / $0122-$0124 / $0127-$012b /
 *   $0164-$016d / $0176-$017a / $0185-$018c / $01c3-$01c9 / $0238-$023f / $025d-$0266 /
 *   $0275-$027d / $0288-$028a / $02a6-$02ad / $02d8-$02e6 / $0308-$0311 / $032d-$0339 /
 *   $0371-$0377 / $03cf-$03d1 / $0438-$044d / $0495-$0498 / $04ba / $05a9-$05ab / $05cd /
 *   $07fe-$0804 / $0936-$0938 / $095a / $0a4f-$0a61 / $0b31-$0b4d / $0b4f / $0b51-$0b71 /
 *   $0b7c-$0b85 / $0e64-$0e68 / $0f51-$0f58 / $0fbe-$0fc5 / $129b-$12a1 / $12c2-$12cb /
 *   $132c-$1337 / $13ad-$13ae / $1428-$142a / $1432 / $145d-$1463 / $1486-$148b /
 *   $149a-$14a5 / $14ae-$14bd / $14e7-$14ee / $14f7-$1508 / $174e-$1765 / $176b-$177b /
 *   $177d / $1785-$178b / $17a6-$17cc / $17d5-$1809 / $191a / $1a11 / $1a1c-$1a23 /
 *   $1b4b-$1b4f / $1b5d-$1b6c / $1bc7-$1bcb / $1bd4-$1bd8 / $1bda-$1be1 / $1c6d-$1c6f /
 *   $1c71-$1c80。$9FD0-$9FFF 为 $FF 填充。
 *   注意: 当前全库无 BANK17_DATA 消费方, 尚未接入音频引擎 (TODO)。
 */
/**
 * bank17 原始字节流。
 * 按 asm 顺序排列, 对应 CPU $8000+ 偏移。
 */
export declare const BANK17_DATA: readonly number[];
export default BANK17_DATA;
